'use strict';
globalThis.AtlasIK = (() => {
 const l1=1,l2=.7;
 function forward(q){return [l1*Math.cos(q[0])+l2*Math.cos(q[0]+q[1]),l1*Math.sin(q[0])+l2*Math.sin(q[0]+q[1])];}
 function reachable(x,y){const r=Math.hypot(x,y);return r>=Math.abs(l1-l2)-1e-9&&r<=l1+l2+1e-9;}
 function solve(x,y,branch=1){if(!reachable(x,y))return null;const c=Math.max(-1,Math.min(1,(x*x+y*y-l1*l1-l2*l2)/(2*l1*l2)));const q2=branch*Math.acos(c);const q1=Math.atan2(y,x)-Math.atan2(l2*Math.sin(q2),l1+l2*Math.cos(q2));return [q1,q2];}
 function step(q,target,lambda=.03){const [a,b]=q;const s=Math.sin(a+b),c=Math.cos(a+b);const j=[[-l1*Math.sin(a)-l2*s,-l2*s],[l1*Math.cos(a)+l2*c,l2*c]];const p=forward(q);const err=[target[0]-p[0],target[1]-p[1]];const aa=j[0][0]**2+j[0][1]**2+lambda**2,bb=j[0][0]*j[1][0]+j[0][1]*j[1][1],dd=j[1][0]**2+j[1][1]**2+lambda**2;const det=aa*dd-bb*bb;const z=[(dd*err[0]-bb*err[1])/det,(-bb*err[0]+aa*err[1])/det];let dq=[j[0][0]*z[0]+j[1][0]*z[1],j[0][1]*z[0]+j[1][1]*z[1]];const scale=Math.min(1,.2/Math.max(1e-12,Math.hypot(...dq)));return q.map((v,i)=>v+dq[i]*scale);}
 return {l1,l2,forward,reachable,solve,step};
})();

