 function renderIndex(params){topic=params.get('topic')||'all';if(!topics.some(t=>t.id===topic))topic='all';direction=params.get('direction')||'all';if(!directions.some(d=>d.id===direction&&d.topic===topic))direction='all';query=params.get('query')||'';track=params.get('track')||'all';$('#guide-topic-tabs').innerHTML=[{id:'all',title:'知识总览'},...topics].map(t=>`<button data-guide-topic="${t.id}" class="${topic===t.id?'active':''}" aria-pressed="${topic===t.id}">${t.title}</button>`).join('');$('#guide-query').value=query;$('#guide-track-filter').value=track;$('#knowledge-index-title').textContent=topic==='all'?'把核心知识串起来。':label(topic);$('#knowledge-index-intro').textContent=topic==='all'?'按方向理解概念、机制与联系。':topics.find(t=>t.id===topic).description;result();}
